import java.util.*;

public class Main {
    static final long MAX_INF = 1000000000000000000L;
    static long result = 0;
    static Long[] memoization;

    static int findMinMoves(long n) {
        if (n == 0) return 0;
        if (n < memoization.length && memoization[(int)n] != null) return memoization[(int)n];

        long previousDiff = MAX_INF;
        long candidate = 1;
        int countSteps = 0;

        while (Math.abs(candidate - n) <= previousDiff) {
            previousDiff = Math.abs(candidate - n);
            candidate = candidate * 10 + 1;
            countSteps++;
        }
        candidate /= 10;

        if (candidate > n && candidate / 10 != 0) {
            if (n < memoization.length) {
                long res1 = countSteps + findMinMoves(Math.abs(candidate - n));
                long res2 = countSteps - 1 + findMinMoves(Math.abs(candidate / 10 - n));
                long minRes = Math.min(res1, res2);
                memoization[(int)n] = minRes;
                return (int) minRes;
            } else {
                long res1 = countSteps + findMinMoves(Math.abs(candidate - n));
                long res2 = countSteps - 1 + findMinMoves(Math.abs(candidate / 10 - n));
                return (int) Math.min(res1, res2);
            }
        }
        if (n < memoization.length) {
            long res = countSteps + findMinMoves(Math.abs(candidate - n));
            memoization[(int)n] = res;
            return (int) res;
        }
        return (int) (countSteps + findMinMoves(Math.abs(candidate - n)));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        memoization = new Long[10000000];
        System.out.println(findMinMoves(n));
        sc.close();
    }
}
